package android.util;import java.io.*;import java.nio.file.*;public final class AtomicFile {private final File base;public AtomicFile(File f){base=f;}public File getBaseFile(){return base;}public FileInputStream openRead()throws IOException{return new FileInputStream(base);}public FileOutputStream startWrite()throws IOException{FileOutputStream out=new FileOutputStream(base);try{Files.setAttribute(base.toPath(),"unix:mode",0600);}catch(Exception e){out.close();throw new IOException(e);}return out;}public void finishWrite(FileOutputStream out)throws IOException{out.close();}public void failWrite(FileOutputStream out){try{out.close();}catch(Exception ignored){}}}